import heapq


class CycleError(Exception):
    pass


def order(deps):
    # Every node mentioned anywhere: keys and everything in their dep lists.
    nodes = set(deps)
    for ds in deps.values():
        nodes.update(ds)

    indeg = {n: 0 for n in nodes}
    dependents = {n: [] for n in nodes}
    for node, ds in deps.items():
        for d in ds:
            indeg[node] += 1
            dependents[d].append(node)

    # Ready nodes, smallest string first; re-evaluated after every pick.
    ready = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(ready)

    out = []
    while ready:
        n = heapq.heappop(ready)
        out.append(n)
        for m in dependents[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(ready, m)

    if len(out) != len(nodes):
        raise CycleError()
    return out

